def generate_fibonacci_series(n_terms):
    series = []
    a, b = 0, 1

    if n_terms <= 0:
        return series
    elif n_terms == 1:
        series.append(a)
    else:
        series.append(a)
        series.append(b)
        for _ in range(2, n_terms):
            next_fib = a + b
            series.append(next_fib)
            a = b
            b = next_fib
    return series

